static void check(BOOL ok,NSString *message){if(!ok){NSLog(@"FAILED %@",message);exit(1);}}
static NSData *encode(id obj){return [NSJSONSerialization dataWithJSONObject:obj options:0 error:NULL];}
static NSData *gzip(NSData *data){z_stream s={0};check(deflateInit2(&s,6,Z_DEFLATED,31,8,Z_DEFAULT_STRATEGY)==Z_OK,@"gzip init");NSMutableData *out=[NSMutableData dataWithLength:compressBound(data.length)+64];s.next_in=(Bytef *)data.bytes;s.avail_in=(uInt)data.length;s.next_out=out.mutableBytes;s.avail_out=(uInt)out.length;check(deflate(&s,Z_FINISH)==Z_STREAM_END,@"gzip fixture");out.length=s.total_out;deflateEnd(&s);return out;}
static BOOL wait(BOOL (^ready)(void),double seconds){NSDate *end=[NSDate dateWithTimeIntervalSinceNow:seconds];while(!ready()&&[end timeIntervalSinceNow]>0)[NSRunLoop.currentRunLoop runUntilDate:[NSDate dateWithTimeIntervalSinceNow:0.01]];return ready();}
int main(int argc,const char **argv){@autoreleasepool{
    NSString *source=@"https://example.com/live.m3u";NSURL *base=[NSURL URLWithString:source];
    NSString *m3u=@"#EXTM3U x-tvg-url=\"guide.xml.gz\"\n#EXTINF:-1 tvg-id=\"cctv1\" group-title=\"央视\",CCTV-1\nlive.m3u8\n#EXTINF:-1,Bad\nfile:///etc/passwd\n";
    NSArray *channels=[M3UParser parse:m3u baseURL:base];check(channels.count==1,@"invalid local media rejected");M3UChannel *c=channels.firstObject;check([c.url isEqual:@"https://example.com/live.m3u8"],@"relative media resolved");check([c.epgID isEqual:@"cctv1"],@"EPG id preserved");check([[M3UParser epgURL:m3u baseURL:base] isEqual:@"https://example.com/guide.xml.gz"],@"relative XMLTV resolved");
    NSString *xml=@"<?xml version=\"1.0\"?><tv><channel id=\"cctv1\"><display-name>CCTV-1</display-name></channel><programme channel=\"cctv1\" start=\"20261023120000 +0800\" stop=\"20261023130000 +0800\"><title>News &amp; Sports</title></programme><programme channel=\"cctv1\" start=\"20261023100000 +0800\" stop=\"20261023110000 +0800\"><title>Earlier</title></programme><programme channel=\"cctv1\" start=\"bad\" stop=\"bad\"><title>Invalid</title></programme></tv>";
    NSData *data=[xml dataUsingEncoding:NSUTF8StringEncoding];NSDictionary *rows=[XMLTVStore parseData:data error:NULL];check([rows[@"cctv1"] count]==2,@"invalid programme rejected");check([rows[@"cctv-1"] isEqual:rows[@"cctv1"]],@"display-name alias supported");check([rows[@"cctv1"][0][@"title"] isEqual:@"Earlier"],@"programmes sorted by time");check([rows[@"cctv1"][1][@"start"] doubleValue]==1792728000,@"XMLTV timezone normalized to UTC");check([rows[@"cctv1"][1][@"title"] isEqual:@"News & Sports"],@"XML escapes parsed");check([[XMLTVStore parseData:gzip(data) error:NULL] isEqual:rows],@"gzip and XML equivalent");check(![XMLTVStore parseData:[@"bad" dataUsingEncoding:NSUTF8StringEncoding] error:NULL],@"malformed XML rejected");check(![XMLTVStore parseData:[gzip(data) subdataWithRange:NSMakeRange(0,12)] error:NULL],@"truncated gzip rejected");
    NSString *local=[@"local-playlist:" stringByAppendingString:NSUUID.UUID.UUIDString];check([ProfileStore isSource:local],@"local profile identifier accepted");check(![ProfileStore isSource:@"local-playlist:../../secret"],@"invalid local profile rejected");[ProfileStore update:source values:@{@"name":@"Test",@"epgURL":@"https://example.com/guide.xml"}];[ProfileStore update:local values:@{@"name":@"Local",@"text":m3u}];
    [NSUserDefaults.standardUserDefaults setObject:@[source,local] forKey:@"subscriptions"];[NSUserDefaults.standardUserDefaults setObject:@[@"cctv1"] forKey:@"favorites"];[NSUserDefaults.standardUserDefaults setObject:@[local,source] forKey:@"profileOrder"];check([[[ProfileStore orderedSources:@[source,local]] firstObject] isEqual:local],@"profile order persisted");[ProfileStore move:source offset:-1 sources:@[source,local]];check([[[ProfileStore orderedSources:@[source,local]] firstObject] isEqual:source],@"profile can move up");
    NSDictionary *snapshot=[HostBackup snapshot];check([HostBackup validatedBackup:encode(snapshot) error:NULL]!=nil,@"v2 local and remote profiles round trip");[HostBackup restore:snapshot];check([[ProfileStore metadata:local][@"text"] isEqual:m3u],@"local playlist survives restore");NSMutableDictionary *bad=[snapshot mutableCopy];bad[@"profiles"]=@{local:@{@"epgURL":@42}};check(![HostBackup validatedBackup:encode(bad) error:NULL],@"malformed metadata rejected");
    NSDictionary *v1=@{@"format":@"CCTVHost",@"version":@1,@"subscriptions":@[source],@"favorites":@[@"cctv1"],@"preferences":@{}};check([HostBackup validatedBackup:encode(v1) error:NULL]!=nil,@"v1 backup remains importable");[HostBackup restore:v1];check([NSUserDefaults.standardUserDefaults dictionaryForKey:@"profileMetadata"].count==0,@"v1 restore clears old profile metadata");
    NSString *url=argc>1?[NSString stringWithUTF8String:argv[1]]:nil;
    if(url){__block BOOL done=NO;__block NSArray *guide;XMLTVStore *store=[XMLTVStore shared];[store loadSource:url channel:@"cctv1" force:YES completion:^(NSArray *r,NSError *e){check(NSThread.isMainThread,@"XMLTV callback main thread");check(!e,@"valid XMLTV downloaded");guide=r;done=YES;}];check(wait(^BOOL{return done;},5),@"download completes");check(guide.count==1,@"HTTP XMLTV guide parsed");done=NO;[store loadSource:url channel:@"cctv1" force:NO completion:^(NSArray *r,NSError *e){check(r.count==1,@"fresh cached guide reused");done=YES;}];check(wait(^BOOL{return done;},2),@"cache completes");
        __block NSInteger completions=0;NSString *slow=[url stringByAppendingString:@"?slow=1"];[store loadSource:slow channel:@"cctv1" force:YES completion:^(NSArray *r,NSError *e){check(e.code==NSURLErrorCancelled,@"startup cancels XMLTV");completions++;}];[store setPaused:YES];check(wait(^BOOL{return completions==1;},1),@"cancellation completes once");[store setPaused:NO];wait(^BOOL{return NO;},1.5);check(completions==1,@"late download cannot complete twice");
    }
    NSLog(@"Native profile and XMLTV tests passed");
}return 0;}
